#!/usr/bin/env python3
"""One-click installer for PermBot's similar-song selection patch.

Run with: python patch.py
The installer backs up modified files and refuses to overwrite unexpected edits.
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
import shutil
import sys
import tempfile
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PATCH_FILES = json.loads(base64.b64decode(
    ""
).decode("utf-8"))
BASE_SHA256 = {
    "cogs/music.py": "747ef812362ec1c86fe3f022b0fcfad83055c41b9b5a578fc900f571c32a6925",
    "README.md": "08a8c186895e0050e22a1dc1aa0d1867ccaebe34daa09ab70bd45ec19cf2d680",
    "tests/test_music_choices.py": None
}
BACKUP_ROOT = ROOT / ".backups"


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def atomic_write(path: Path, content: bytes, previous_mode: int | None) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    temp_path = Path(temp_name)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        if previous_mode is not None:
            os.chmod(temp_path, previous_mode)
        os.replace(temp_path, path)
    finally:
        temp_path.unlink(missing_ok=True)


def main() -> int:
    repo_root = ROOT.resolve()
    if not (ROOT / "cogs" / "music.py").is_file() or not (ROOT / "README.md").is_file():
        print("Run patch.py from the PermBot repository root.", file=sys.stderr)
        return 1

    planned = []
    conflicts = []
    for relative_path, text in PATCH_FILES.items():
        target = (ROOT / relative_path).resolve()
        if not target.is_relative_to(repo_root):
            conflicts.append(f"Unsafe patch path: {relative_path}")
            continue

        new_content = text.encode("utf-8")
        new_hash = sha256(new_content)
        if target.is_file():
            current = target.read_bytes()
            current_hash = sha256(current)
            if current_hash == new_hash:
                print(f"[ALREADY INSTALLED] {relative_path}")
                continue
            expected_hash = BASE_SHA256.get(relative_path)
            if expected_hash is None or current_hash != expected_hash:
                conflicts.append(
                    f"{relative_path} has unexpected contents; no files were changed. "
                    "Restore the expected PermBot version or apply the patch manually."
                )
                continue
            planned.append((relative_path, target, new_content, current))
        else:
            if BASE_SHA256.get(relative_path) is not None:
                conflicts.append(f"Required file is missing: {relative_path}")
                continue
            planned.append((relative_path, target, new_content, None))

    if conflicts:
        for message in conflicts:
            print(f"ERROR: {message}", file=sys.stderr)
        return 1
    if not planned:
        print("Song-choice patch is already installed.")
        return 0

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup_dir = BACKUP_ROOT / f"song_choice_patch_{stamp}"
    existing = [(rel, path, content) for rel, path, _, content in planned if content is not None]
    if existing:
        backup_dir.mkdir(parents=True, exist_ok=False)
        for relative_path, _, original in existing:
            backup_path = backup_dir / relative_path
            backup_path.parent.mkdir(parents=True, exist_ok=True)
            backup_path.write_bytes(original)

    applied = []
    try:
        for relative_path, target, new_content, original in planned:
            previous_mode = target.stat().st_mode if target.exists() else None
            atomic_write(target, new_content, previous_mode)
            applied.append((relative_path, target, original))
            action = "UPDATED" if original is not None else "CREATED"
            print(f"[{action}] {relative_path}")
    except Exception as error:
        print(f"ERROR: Installation failed; restoring previous files: {error}", file=sys.stderr)
        for _, target, original in reversed(applied):
            try:
                if original is None:
                    target.unlink(missing_ok=True)
                else:
                    atomic_write(target, original, target.stat().st_mode)
            except OSError as rollback_error:
                print(f"ERROR: Could not restore {target}: {rollback_error}", file=sys.stderr)
        return 1

    if existing:
        print(f"Backups saved in: {backup_dir.relative_to(ROOT)}")
    print("Song-choice patch installed successfully.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
